def tally(words):
    """Return a dictionary mapping each word to its frequency."""
    count = {}
    for w in words:
        count[w] = count.get(w, 0) + 1
    return count


def top(words, n):
    """Return the n most frequent words as (word, frequency) tuples, sorted by frequency descending then alphabetically."""
    count = tally(words)
    items = sorted(count.items(), key=lambda kv: (-kv[1], kv[0]))
    return items[:n]


def merge(a, b):
    """Return a new dictionary combining the counts from dictionaries a and b."""
    count = dict(a)
    for k, v in b.items():
        count[k] = count.get(k, 0) + v
    return count
